export function getGAMLAProfile(acNo: number): MLAProfile | undefined {
  return GA_MLA_PROFILES.find(p => p.acNo === acNo);
}

export function getGAMLAsByParty(party: string): MLAProfile[] {
  return GA_MLA_PROFILES.filter(p => p.party === party);
}

export function getGAFemaleMLAs(): MLAProfile[] {
  return GA_MLA_PROFILES.filter(p => p.gender === 'F');
}
